/* Swedish Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Lars": "crowned with laurel — Latin Laurentius", "Anna": "grace — Hebrew Hannah", "Karl": "free man — Old Norse karl", "Ingrid": "Ing's beauty — Old Norse", "Erik": "eternal ruler — Old Norse ei + rikr", "Astrid": "god-beautiful — Old Norse", "Andersson": "The most common Swedish surname.", "Johansson": "Among the most common surnames.", "Karlsson": "A classic -son surname.", "Lindqvist": "A classic nature compound surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Lars';
console.log(lookup(q));

